WITH lines AS (SELECT id, created_at, coupon_codes, k, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) e AS k, attr_value) SELECT k, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, COUNT_IF(k = 'gift') AS gift_events, COUNT(CASE WHEN k = 'utm_source' THEN 1 END) AS utm_source_count, SIZE(COLLECT_SET(k)) AS num_ks, COUNT_IF(k = 'utm_source') AS utm_source_events FROM lines GROUP BY ROLLUP (k) ORDER BY utm_source_count DESC NULLS FIRST;
